INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', 'CLMBR is a vertical machine that mimics climbing. The movement works arms, legs and glutes at once, so separate arm and leg days become one workout. The load is low-impact, so the machine suits people of different ages and levels and can be used for life. The company cites research showing higher heart rate and oxygen consumption during vertical climbing than during treadmill running or rowing, and up to 600 calories burned in a 30-minute session. CLMBR comes in home and commercial versions for gyms and studios. The membership unlocks instructor-led classes, levels and a user community.', 'manual' FROM DUAL WHERE @new = 1;
