SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'komoot.com' OR LOWER(`name`) = LOWER('komoot'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'komoot', NULL, 'https://www.komoot.com', NULL, NULL, 'komoot — планувальник маршрутів і навігатор для велосипеда, походів і бігу: будує маршрути під конкретний вид спорту (шосе, MTB-сингли, стежки), надихає рекомендаціями великої спільноти. Є голосова навігація.', 'komoot is a route planner and navigator for cycling, hiking and running: it builds sport-specific routes (road, MTB singletrack, trails) and inspires you with recommendations from a large community.', 'komoot перетворює наступну поїздку, похід чи пробіжку на пригоду. Планувальник маршрутів генерує маршрути з урахуванням виду спорту та ваших уподобань: рівний асфальт для шосейного велосипеда, сингли для гірського байка чи спокійні стежки для пішого походу. Знайти натхнення допомагають рекомендації та знання спільноти — любителі активного відпочинку діляться місцями й маршрутами. Із безплатним акаунтом можна знаходити, налаштовувати маршрути й орієнтуватися за ними в мобільному застосунку з голосовою навігацією. Маршрутами й пригодами можна ділитися з друзями. Застосунок доступний в App Store і Google Play.', 'komoot turns your next ride, hike or run into an adventure. The route planner generates routes based on your sport and preferences: smooth asphalt for a road bike, singletrack for a mountain bike or peaceful trails for a hike. Inspiration comes from community knowledge and recommendations — outdoor enthusiasts share places and routes. With a free account you can find, customize and navigate routes in the mobile app with voice navigation. Routes and adventures can be shared with friends. The app is available on the App Store and Google Play.', 'Планувальник маршрутів під вид спорту
Шосе, MTB, походи й біг
Рекомендації спільноти
Навігація в застосунку
Безплатний акаунт', 'Sport-specific route planner
Road, MTB, hiking and running
Community recommendations
In-app navigation
Free account', 'Велосипедисти, туристи й бігуни, які планують маршрути на природі.', 'Cyclists, hikers and runners planning outdoor routes.', 'web,mobile', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
