SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'myswimpro.com' OR LOWER(`name`) = LOWER('MySwimPro'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'MySwimPro', NULL, 'https://myswimpro.com', NULL, NULL, 'MySwimPro — персональний тренер з плавання в застосунку: AI-тренування й плани, відстеження запливів і аналітика, відео техніки та вправ, синхронізація з годинником, а також сертифікація тренерів і плавальні ретрити.', 'MySwimPro is a personal swim coach in an app: AI workouts and plans, swim tracking and analytics, technique videos and drills, watch sync, plus swim coach certification and swim retreats.', 'MySwimPro допомагає плавцям покращити техніку, підтягнути форму й плавати швидше за перевіреною методикою. Застосунок складає персональні тренування й плани за допомогою AI, тож не потрібно самостійно писати програми. Він відстежує запливи й показує аналітику, містить відео з технікою та вправами, синхронізується з годинниками. Крім застосунку, MySwimPro пропонує програму сертифікації тренерів з плавання MySwimPro University та всеосяжні плавальні ретрити для дорослих, де експерти тиждень працюють над ефективністю плавання. Для застосунку доступний безплатний пробний період. Застосунок підходить і новачкам, і досвідченим плавцям.', 'MySwimPro helps swimmers improve technique, get in shape and swim faster with a proven coaching methodology. The app builds personalized workouts and training plans with AI, so you don''t have to write your own. It tracks swims and shows analytics, includes technique videos and drills, and syncs with watches. Beyond the app, MySwimPro offers the MySwimPro University swim coach certification and all-inclusive swim retreats for adults, where experts spend a week on swimming efficiency. The app has a free trial. The app suits beginners and experienced swimmers.', 'AI-тренування й плани для плавців
Відстеження запливів і аналітика
Відео техніки та вправ
Синхронізація з годинниками
Сертифікація тренерів
Плавальні ретрити', 'AI workouts and plans for swimmers
Swim tracking and analytics
Technique videos and drills
Watch sync
Coach certification
Swim retreats', 'Плавці-аматори, триатлоністи, а також тренери з плавання.', 'Recreational swimmers, triathletes and swim coaches.', 'mobile', 'none', 'published', 0, 'found', @uid, '2026-10-04 00:00:00' FROM DUAL WHERE @new = 1;
