INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'short_description', 'en', 'GoldenCheetah is free, open-source power data analysis software for cyclists and triathletes: import from Garmin, SRM, PowerTap and more, with a rich set of analysis tools for Linux, macOS and Windows.', 'manual' FROM DUAL WHERE @new = 1;
INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', 'GoldenCheetah starts from the belief that cyclists and triathletes should be able to download their power data to their own computer and analyze it without restrictions. It downloads or imports ride data directly from many Garmin, SRM, PowerTap and O_Synce devices, as well as files from other manufacturers'' software and TrainingPeaks WKO+. It offers a rich set of analysis tools — from power curves to load and recovery models. GoldenCheetah runs on Linux, macOS and Windows, is released under an open-source license and is developed by a community of contributors. The site has downloads, features, tutorials and science resources.', 'manual' FROM DUAL WHERE @new = 1;
