SET @new = IF(NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'prismlabs.tech' OR LOWER(`name`) = LOWER('Prism Labs'))), 1, 0);
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_by`, `created_at`) SELECT 'Prism Labs', NULL, 'https://www.prismlabs.tech', NULL, NULL, 'Prism Labs — точні 3D-скани тіла й аналіз складу тіла з камери смартфона на iOS та Android, валідовані незалежною лабораторією: для програм схуднення, страхування, клінік, фармацевтики, фітнес- і корпоративних платформ.', 'Prism Labs delivers accurate 3D body scans and body composition from a smartphone camera on iOS and Android, validated by an independent lab, for weight loss programs, insurance, clinics, pharma, fitness and corporate platforms.', 'Prism Labs дозволяє отримувати 3D-скани тіла та дані про його склад просто з камери мобільного телефона на iOS та Android. Точність і відтворюваність вимірювань підтверджено незалежною дослідницькою лабораторією. Технологію пропонують партнерам через API: програмам схуднення, зокрема з препаратами GLP-1, страховим компаніям і програмам здоров''я населення, керуванню хронічними хворобами, лікарям і системам охорони здоров''я для віддаленого моніторингу, фармацевтиці та клінічним дослідженням, фітнес- і велнес-платформам для залучення учасників, а також корпоративним велнес-програмам. Модель ціноутворення не обмежує кількість сканувань.', 'Prism Labs lets you get 3D body scans and body composition data from a mobile phone camera on iOS and Android. Accuracy and precision are validated by an independent research laboratory. The technology is offered to partners via API: weight loss programs, including GLP-1 programs, insurers and population health programs, chronic disease management, healthcare providers for remote monitoring, pharma and clinical trials, fitness and wellness platforms for member engagement, and corporate wellness programs. Pricing does not limit how often users scan.', '3D-скан тіла з камери смартфона
Аналіз складу тіла
