INSERT IGNORE INTO `product_categories` (`product_id`, `category_id`) SELECT @pid, c.`id` FROM `categories` c WHERE @pid IS NOT NULL AND c.`slug` = 'sports' LIMIT 1;
INSERT IGNORE INTO `product_subcategories` (`product_id`, `subcategory_id`) SELECT @pid, s.`id` FROM `subcategories` s JOIN `categories` c ON c.`id` = s.`category_id` WHERE @pid IS NOT NULL AND c.`slug` = 'sports' AND s.`name` = 'Аналітика, скаутинг та суддівство' LIMIT 1;
INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'short_description', 'en', 'WSC Sports is an AI sports content platform: automatic creation, management and distribution of personalized highlights for teams, leagues and broadcasters, producing thousands of clips for digital platforms in minutes.', 'manual' FROM DUAL WHERE @new = 1;
INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'full_description', 'en', 'WSC Sports pioneered AI-tailored sports content experiences for fans. Its all-in-one platform automates video management, creation and distribution: AI analyzes broadcasts, finds key moments and builds personalized highlights and clips for every digital platform. Teams, leagues and broadcasters worldwide can release huge volumes of content quickly — one client says that over 1,000 highlight packages can now be created in a few minutes. The main benefits are speed, scale and fan focus. The site covers the Arena platform, client stories, a blog and demo requests.', 'manual' FROM DUAL WHERE @new = 1;
INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'main_features', 'en', 'AI highlights from broadcasts
Personalized fan content
Distribution to digital platforms
Scale and speed
Arena platform', 'manual' FROM DUAL WHERE @new = 1;
INSERT IGNORE INTO `product_translations` (`product_id`, `field_name`, `lang`, `translated_text`, `source`) SELECT @pid, 'target_audience', 'en', 'Sports leagues, clubs, broadcasters and media.', 'manual' FROM DUAL WHERE @new = 1;
